11	// Author: Zhang, Qi
12	// Description:icache
13	`timescale 1ns/1ns
14	
15	`include "define.v"
16	
17	module instruction_cache (
18	  input                                 clk               ,
19	  input                                 rst_n             ,
20	
21	  input                                 invalid_i         ,
22	  //output                                core_req_ready_o  ,
23	  input                                 core_req_valid_i  ,
24	  input  [`XLEN-1:0]                    core_req_addr_i   ,
25	  input  [`NUM_FETCH-1:0]               core_req_mask_i   ,
26	  input  [`DEPTH_WARP-1:0]              core_req_wid_i    ,
27	
28	  input                                 flush_pipe_valid_i,
29	  input  [`DEPTH_WARP-1:0]              flush_pipe_wid_i  ,
30	
31	  output                                core_rsp_valid_o  ,
32	  output [`XLEN-1:0]                    core_rsp_addr_o   ,
33	  output [`NUM_FETCH*`XLEN-1:0]         core_rsp_data_o   ,
34	  output [`NUM_FETCH-1:0]               core_rsp_mask_o   ,
35	  output [`DEPTH_WARP-1:0]              core_rsp_wid_o    ,
36	  output                                core_rsp_status_o , //0 is hit, 1 is miss
37	
38	  output                                mem_rsp_ready_o   ,
39	  input                                 mem_rsp_valid_i   ,
40	  input  [`DEPTH_WARP-1:0]              mem_rsp_d_source_i,
41	  input  [`XLEN-1:0]                    mem_rsp_d_addr_i  ,
42	  input  [`DCACHE_BLOCKWORDS*`XLEN-1:0] mem_rsp_d_data_i  , //[`XLEN-1:0] [0:`DCACHE_BLOCKWORDS-1]
43	                                                            //DCACHE_BLOCKWORDS=NUM_THREAD
44	
45	  input                                 mem_req_ready_i   ,
46	  output                                mem_req_valid_o   ,
47	  output [`WIDBITS-1:0]                 mem_req_a_source_o,
48	  output [`XLEN-1:0]                    mem_req_a_addr_o   
49	  );
50	
51	  localparam BLOCK_BITS = `DCACHE_BLOCKWORDS*32                       ,
52	             BA_BITS    = `DCACHE_TAGBITS+`DCACHE_SETIDXBITS          ,
53	             FIFO_BITS  = `DEPTH_WARP+`XLEN+(`DCACHE_BLOCKWORDS*`XLEN);
54	
55	  wire dataAccess_r_req_valid;
56	  wire [`DCACHE_NWAYS*BLOCK_BITS-1:0] dataAccess_w_req_data;
57	  wire [`DCACHE_NWAYS*BLOCK_BITS-1:0] dataAccess_data; //[BLOCK_BITS-1:0] [0:`DCACHE_NWAYS-1]
58	
59	  wire tagAccess_r_req_valid;
60	  wire [`DCACHE_SETIDXBITS-1:0] tagAccess_r_req_setid;
61	  wire [`DCACHE_TAGBITS-1:0] tagAccess_tagFromCore_st1;
62	  wire [`DCACHE_SETIDXBITS-1:0] tagAccess_w_req_setid;
63	  wire [`DCACHE_TAGBITS*`DCACHE_NWAYS-1:0] tagAccess_w_req_data; 
64	  wire [`DCACHE_TAGBITS-1:0] tagAccess_w_req_data_scalar;
65	  wire [`DCACHE_WAYIDXBITS-1:0] wayid_hit_st1; //bin
66	  wire tagAccess_hit_st1;
67	  wire [`DCACHE_WAYIDXBITS-1:0] wayid_replace_st0; //bin
68	  wire [`DCACHE_NSETS*`DCACHE_WAYIDXBITS-1:0] tagAccess_wayid_replacement;
69	  wire [`DCACHE_NWAYS-1:0] wayid_replace_st0_one;
70	
71	  wire [BA_BITS-1:0] mshrAccess_miss_req_block_addr;
72	  wire [`DEPTH_WARP-1:0] mshrAccess_miss_req_target_info;
73	  wire mshrAccess_miss_rsp_in_ready;
74	  wire [BA_BITS-1:0] mshrAccess_miss_rsp_in_block_addr;
75	  wire [BA_BITS-1:0] mshrAccess_miss_rsp_out_block_addr;
76	  wire [BA_BITS-1:0] mshrAccess_miss2mem_block_addr;
77	
78	  wire memRsp_fire;
79	  wire memRsp_valid;
80	  wire [FIFO_BITS-1:0] memRsp_data_i;
81	  wire [FIFO_BITS-1:0] memRsp_data_o;
82	  wire [`DEPTH_WARP-1:0] mem_rsp_d_source_o;
83	  wire [`XLEN-1:0] mem_rsp_d_addr_o;  
84	  wire [`DCACHE_BLOCKWORDS*`XLEN-1:0] mem_rsp_d_data_o; //[`XLEN-1:0] [0:DCACHE_BLOCKWORDS-1]  
85	    
86	  wire [BLOCK_BITS-1:0] data_after_wayid_st1;
87	
88	  wire shouldFlushCoreRsp_st0,shouldFlushCoreRsp_st1;
89	
90	  wire /*cacheHit_st1,*/cacheMiss_st1;
91	  wire order_violation_st1;
92	  wire status_st1,status_st2;
93	
94	  reg [`DEPTH_WARP-1:0] wid_st1,wid_st2,wid_st3;
95	  reg [`XLEN-1:0]       addr_st1,addr_st2;    
96	  reg [`NUM_FETCH-1:0]  mask_st1,mask_st2;
97	  reg core_req_fire_st1,core_req_fire_st2;
98	  reg [BLOCK_BITS-1:0] data_after_wayid_st2;
99	  reg shouldFlushCoreRsp_st0_r,shouldFlushCoreRsp_st1_r;
100	  reg order_violation_st2,order_violation_st3;
101	  reg status_st1_r;
102	  reg cacheMiss_st2,cacheMiss_st3;
103	
104	  assign wayid_replace_st0 = tagAccess_wayid_replacement[(`DCACHE_WAYIDXBITS*(tagAccess_w_req_setid+1)-1)-:`DCACHE_WAYIDXBITS];
105	
106	  always @(posedge clk or negedge rst_n) begin
107	    if(!rst_n) begin
108	      wid_st1 <= 'h0;
109	      wid_st2 <= 'h0;
110	      wid_st3 <= 'h0;
111	      addr_st1 <= 'h0;
112	      addr_st2 <= 'h0;
113	      mask_st1 <= 'h0;
114	      mask_st2 <= 'h0;
115	      core_req_fire_st1 <= 'h0;
116	      core_req_fire_st2 <= 'h0;
117	      data_after_wayid_st2 <= 'h0;
118	      order_violation_st2 <= 'h0;
119	      order_violation_st3 <= 'h0;
120	      shouldFlushCoreRsp_st0_r <= 'h0;
121	      shouldFlushCoreRsp_st1_r <= 'h0;
122	      status_st1_r <= 'h0;
123	      cacheMiss_st2 <= 'h0;
124	      cacheMiss_st3 <= 'h0;
125	    end 
126	    else begin
127	      wid_st1 <= core_req_wid_i;
128	      wid_st2 <= wid_st1;
129	      wid_st3 <= wid_st2;
130	      addr_st1 <= core_req_addr_i;
131	      addr_st2 <= addr_st1;
132	      mask_st1 <= core_req_mask_i;
133	      mask_st2 <= mask_st1;
134	      core_req_fire_st1 <= (core_req_valid_i && !shouldFlushCoreRsp_st0);
135	      core_req_fire_st2 <= (core_req_fire_st1 && !shouldFlushCoreRsp_st1);
136	      data_after_wayid_st2 <= data_after_wayid_st1;
137	      order_violation_st2 <= order_violation_st1;
138	      order_violation_st3 <= order_violation_st2;
139	      shouldFlushCoreRsp_st0_r <= shouldFlushCoreRsp_st0;
140	      shouldFlushCoreRsp_st1_r <= shouldFlushCoreRsp_st1;
141	      status_st1_r <= status_st1;
142	      cacheMiss_st2 <= shouldFlushCoreRsp_st1 ? 'h0 : cacheMiss_st1;
143	      cacheMiss_st3 <= cacheMiss_st2;
144	    end 
145	  end 
146	
147	  //assign core_req_ready_o = 1'h1;
148	
149	  //assign cacheHit_st1 = (tagAccess_hit_st1 && core_req_fire_st1);
150	  assign cacheMiss_st1 = (!tagAccess_hit_st1 && core_req_fire_st1);
151	
152	  assign shouldFlushCoreRsp_st0 = (core_req_wid_i == flush_pipe_wid_i) && flush_pipe_valid_i;
153	  assign shouldFlushCoreRsp_st1 = (wid_st1 == flush_pipe_wid_i) && flush_pipe_valid_i;
154	
155	  assign tagAccess_r_req_valid = core_req_valid_i && (!shouldFlushCoreRsp_st0);
156	  assign tagAccess_tagFromCore_st1 = addr_st1 >> (`XLEN-`DCACHE_TAGBITS);
157	  assign tagAccess_w_req_data_scalar = mshrAccess_miss_rsp_out_block_addr >> (BA_BITS-`DCACHE_TAGBITS);
158	  assign tagAccess_w_req_data = {`DCACHE_NWAYS{tagAccess_w_req_data_scalar}};
159	
160	  assign mshrAccess_miss_req_block_addr = addr_st1 >> (`XLEN-(`DCACHE_TAGBITS+`DCACHE_SETIDXBITS));
161	  assign mshrAccess_miss_req_target_info = {wid_st1,addr_st1[`DCACHE_BLOCKOFFSETBITS+`DCACHE_WORDOFFSETBITS-1:0]};
162	  assign mshrAccess_miss_rsp_in_block_addr = mem_rsp_d_addr_o >> (`XLEN-(`DCACHE_TAGBITS+`DCACHE_SETIDXBITS));
163	
164	  assign mem_req_a_addr_o = {mshrAccess_miss2mem_block_addr,{(32-BA_BITS){1'h0}}};
165	
166	  assign dataAccess_r_req_valid = core_req_valid_i && !shouldFlushCoreRsp_st0;
167	
168	  assign dataAccess_w_req_data = {`DCACHE_NWAYS{mem_rsp_d_data_o}};
169	
170	  assign data_after_wayid_st1 = dataAccess_data[(wayid_hit_st1+1)*BLOCK_BITS-1 -: BLOCK_BITS];
171	  
172	  //assign core_rsp_valid_o = core_req_fire_st2 && !order_violation_st2;
173	  assign core_rsp_valid_o = core_req_fire_st2;
174	  //assign core_rsp_data_o = data_after_block_offset_st2;
175	  assign core_rsp_data_o = data_after_wayid_st2;
176	  assign core_rsp_wid_o = wid_st2;
177	  assign core_rsp_mask_o = mask_st2;
178	  assign core_rsp_addr_o = addr_st2;
179	
180	  assign status_st1 = shouldFlushCoreRsp_st0_r ? 1'b0 : cacheMiss_st1; 
181	  assign status_st2 = shouldFlushCoreRsp_st1_r ? 1'b0 : status_st1_r; 
182	
183	  assign core_rsp_status_o = status_st2;
184	
185	  assign memRsp_fire = memRsp_valid && mshrAccess_miss_rsp_in_ready;
186	  assign memRsp_data_i = {mem_rsp_d_data_i,mem_rsp_d_addr_i,mem_rsp_d_source_i};
187	  assign {mem_rsp_d_data_o,mem_rsp_d_addr_o,mem_rsp_d_source_o} = memRsp_data_o;
188	
189	  assign order_violation_st1 = ((wid_st1 == wid_st2) && cacheMiss_st2 && !order_violation_st2) ||
190	                               ((wid_st1 == wid_st3) && cacheMiss_st3 && !order_violation_st3);
191	
192	  get_setid #(
193	    .DATA_WIDTH      (`XLEN                  ),
194	    .XLEN            (`XLEN                  ),
195	    .SETIDXBITS      (`DCACHE_SETIDXBITS     ),
196	    .BLOCK_OFFSETBITS(`DCACHE_BLOCKOFFSETBITS),
197	    .WORD_OFFSETBITS (`DCACHE_WORDOFFSETBITS ),
198	    .BA_BITS         (BA_BITS                )
199	    ) get_setid_tagAccess_r_req(
200	    .data_i(core_req_addr_i      ), 
201	    .data_o(tagAccess_r_req_setid)
202	    );
203	
204	  get_setid #(
205	    .DATA_WIDTH      (BA_BITS                ),
206	    .XLEN            (`XLEN                  ),
207	    .SETIDXBITS      (`DCACHE_SETIDXBITS     ),
208	    .BLOCK_OFFSETBITS(`DCACHE_BLOCKOFFSETBITS),
209	    .WORD_OFFSETBITS (`DCACHE_WORDOFFSETBITS ),
210	    .BA_BITS         (BA_BITS                )
211	    ) get_setid_tagAccess_w_req(
212	    .data_i(mshrAccess_miss_rsp_out_block_addr), 
213	    .data_o(tagAccess_w_req_setid             )
214	    );
215	 
216	  tag_access_icache #(
217	    .TAG_WIDTH(`DCACHE_TAGBITS   ),
218	    .NUM_SET  (`DCACHE_NSETS     ),
219	    .NUM_WAY  (`DCACHE_NWAYS     ), 
220	    .SET_DEPTH(`DCACHE_SETIDXBITS), 
221	    .WAY_DEPTH(`DCACHE_WAYIDXBITS) 
222	    ) tagAccess(
223	    .clk                (clk                        ),
224	    .rst_n              (rst_n                      ),
225	    .invalid_i          (invalid_i                  ),
226	    .r_req_valid_i      (tagAccess_r_req_valid      ),
227	    .r_req_setid_i      (tagAccess_r_req_setid      ),
228	    .tagFromCore_st1_i  (tagAccess_tagFromCore_st1  ),
229	    .w_req_valid_i      (memRsp_fire                ),
230	    .w_req_setid_i      (tagAccess_w_req_setid      ),
231	    .w_req_data_i       (tagAccess_w_req_data       ),
232	    .wayid_replacement_o(tagAccess_wayid_replacement),
233	    .wayid_hit_st1_o    (wayid_hit_st1              ),
234	    .hit_st1_o          (tagAccess_hit_st1          )
235	    ); 
236	
237	  bin2one #(
238	    .ONE_WIDTH(`DCACHE_NWAYS     ),
239	    .BIN_WIDTH(`DCACHE_WAYIDXBITS)
240	    ) b2o(
241	    .bin(wayid_replace_st0    ),
242	    .oh (wayid_replace_st0_one)
243	    );
244	
245	  sram_template #(
246	    .GEN_WIDTH(BLOCK_BITS        ), 
247	    .NUM_SET  (`DCACHE_NSETS     ), 
248	    .NUM_WAY  (`DCACHE_NWAYS     ), 
249	    .SET_DEPTH(`DCACHE_SETIDXBITS),
250	    .WAY_DEPTH(`DCACHE_WAYIDXBITS)
251	    ) dataAccess(
252	    .clk            (clk                   ),
253	    .rst_n          (rst_n                 ),
254	    .r_req_valid_i  (dataAccess_r_req_valid),
255	    .r_req_setid_i  (tagAccess_r_req_setid ),
256	    .r_resp_data_o  (dataAccess_data       ),
257	    .w_req_valid_i  (memRsp_fire           ),
258	    .w_req_setid_i  (tagAccess_w_req_setid ),
259	    .w_req_waymask_i(wayid_replace_st0_one ),
260	    .w_req_data_i   (dataAccess_w_req_data )
261	    );
262	
263	  mshr_icache #(
264	    .TI_WIDTH       (`WIDBITS              ), 
265	    .BA_BITS        (BA_BITS               ),
266	    .WID_BITS       (`DEPTH_WARP           ), 
267	    .NUM_ENTRY      (`DCACHE_MSHRENTRY     ), 
268	    .NUM_SUB_ENTRY  (`DCACHE_MSHRSUBENTRY  ), 
269	    .ENTRY_DEPTH    (`DCACHE_ENTRY_DEPTH   ), 
270	    .SUB_ENTRY_DEPTH(`DCACHE_SUBENTRY_DEPTH) 
271	    ) mshrAccess(
272	    .clk                      (clk                               ),
273	    .rst_n                    (rst_n                             ),
274	    .miss_req_valid_i         (cacheMiss_st1                     ),
275	    .miss_req_block_addr_i    (mshrAccess_miss_req_block_addr    ),
276	    .miss_req_target_info_i   (mshrAccess_miss_req_target_info   ),
277	    .miss_rsp_in_ready_o      (mshrAccess_miss_rsp_in_ready      ),
278	    .miss_rsp_in_valid_i      (memRsp_valid                      ),
279	    .miss_rsp_in_block_addr_i (mshrAccess_miss_rsp_in_block_addr ),
280	    .miss_rsp_out_ready_i     (1'h1                              ),
281	    .miss_rsp_out_block_addr_o(mshrAccess_miss_rsp_out_block_addr),
282	    .miss2mem_ready_i         (mem_req_ready_i                   ),
283	    .miss2mem_valid_o         (mem_req_valid_o                   ),
284	    .miss2mem_block_addr_o    (mshrAccess_miss2mem_block_addr    ),
285	    .miss2mem_instr_id_o      (mem_req_a_source_o                )
286	    );      
287	
288	  stream_fifo_pipe_true #(
289	    .DATA_WIDTH(FIFO_BITS),
290	    .FIFO_DEPTH(2        )
291	    ) memRsp(
292	    .clk      (clk                         ),
293	    .rst_n    (rst_n                       ),
294	    .w_ready_o(mem_rsp_ready_o             ),
295	    .w_valid_i(mem_rsp_valid_i             ),
296	    .w_data_i (memRsp_data_i               ),
297	    .r_valid_o(memRsp_valid                ),
298	    .r_ready_i(mshrAccess_miss_rsp_in_ready),
299	    .r_data_o (memRsp_data_o               )
300	    );
301	
302	endmodule
303

